    #     i1 = A2 (AND pair 0)
    #     i2 = B1 (AND pair 1)
    #     i3 = B2 (AND pair 1)
    #   ports_dict example: {"A1":"i0","A2":"i1","B1":"i2","B2":"i3","Y":"o0",...}
